jQuery(function ($) {
  let $ReviewersSlider = $('.reviews-slider');
  function slickify() {
    $ReviewersSlider.slick({
      slidesToShow: 1,
      slidesToScroll: 1,
      arrows: true,
      dots: false,
      autoplay: false,
      infinite: true,
      autoplaySpeed: 5000,
      speed: 500,
      cssEase: "ease-in-out",
    });
  }

  slickify();
});